#pragma once
#include "../App/BrowserToolPolicy.h"
#include "../App/BrowserPrivateText.h"
#include <fstream>

namespace coincide {
inline int browser_tool_tests(const std::filesystem::path& report){
    std::size_t checks{};const auto check=[&](bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);};const auto rejects=[&](const std::string& request,const char* message){bool failed{};try{browser_tool::Request::parse(request);}catch(...){failed=true;}check(failed,message);};
    try{
        using browser_tool::Request;check(Request::parse("{\"action\":\"read\"}").action=="read","bounded read must work without a network destination");check(Request::parse("{\"action\":\"read\",\"tab\":\"{abcdef12-3456-7890-abcd-0123456789ab}\",\"frame\":\"observed-frame\"}").tab.size()==38,"existing persisted braced browser identities must remain addressable");
        rejects("{\"action\":\"read\",\"script\":\"document.cookie\"}","browser requests must not add arbitrary JavaScript");rejects("{\"action\":\"evaluate\",\"source\":\"document.cookie\"}","script execution must not be a browser action");rejects("{\"action\":\"read\",\"action\":\"navigate\",\"url\":\"https://example.com\"}","duplicate action keys must not route two different commands");rejects("{\"action\":\"read\",\"\\u0061ction\":\"read\"}","escaped duplicate keys must not bypass action validation");
        rejects("{\"action\":\"navigate\",\"url\":\"file:///C:/Windows/win.ini\"}","navigation must not become arbitrary local-file reading");rejects("{\"action\":\"navigate\",\"url\":\"javascript:alert(1)\"}","navigation must not accept script schemes");rejects("{\"action\":\"navigate\",\"url\":\"https://user:secret@example.com\"}","browser navigation must not put credentials in URL authority");rejects("{\"action\":\"screenshot\",\"output_path\":\"C:/outside.png\"}","screenshot destinations must be app-owned C++ context, not caller-selected paths");
        rejects("{\"action\":\"read\",\"page\":1.5}","read pagination must use whole bounded pages");rejects("{\"action\":\"read\",\"page\":1001}","page reads must remain bounded");rejects("{\"action\":\"input\",\"selector\":\"\",\"text\":\"test\"}","input needs an explicit nonempty selector");check(Request::parse("{\"action\":\"input\",\"selector\":\"#owned\",\"text\":\"\"}").action=="input","explicitly clearing a selected input must be supported");
        rejects("{\"action\":\"wait-for\",\"timeout\":1}","wait-for must name visible text or a selector");rejects("{\"action\":\"wait-for\",\"text\":\"ready\",\"timeout\":61}","browser polling must have a deadline");check(Request::parse("{\"action\":\"wait-for\",\"selector\":\"#owned\",\"timeout\":0.5}").timeout==std::chrono::milliseconds(5500),"wait-for deadlines must include only their bounded response margin");
        rejects("{\"action\":\"scroll\",\"to\":\"bottom\",\"by\":2}","scroll targets must be mutually exclusive");rejects("{\"action\":\"viewport\",\"reset\":true,\"width\":400}","reset must not hide conflicting viewport settings");check(Request::parse("{\"action\":\"viewport\",\"preset\":\"mobile\"}").action=="viewport","named native viewport presets must be supported");rejects("{\"action\":\"viewport\",\"width\":319,\"height\":500}","viewport width must remain bounded");
        rejects("{\"action\":\"upload\",\"selector\":\"#file\",\"files\":[\"relative.txt\"]}","uploads must name explicit absolute local files");rejects("{\"action\":\"upload\",\"selector\":\"#file\",\"files\":[\"C:/owned.txt\"],\"authorization\":true}","upload authorization must never come from request JSON");
        check(browser_tool::Key::parse("Meta+a").modifiers==2&&browser_tool::Key::parse("Ctrl+A").text.empty(),"Mac primary-modifier spelling must map to Windows page Ctrl editing without emitting text");check(browser_tool::Key::parse("Shift+Tab").virtual_key==9&&browser_tool::Key::parse("Enter").text=="\r","native page navigation/editing key events must retain correct key codes");
        rejects("{\"action\":\"press\",\"key\":\"Ctrl+V\"}","agent key input must not expose the system clipboard");rejects("{\"action\":\"press\",\"key\":\"Shift+Delete\"}","agent keys must not invoke the Windows cut shortcut");rejects("{\"action\":\"press\",\"key\":\"Alt+F4\"}","page input must not control native desktop windows");rejects("{\"action\":\"press\",\"key\":\"Ctrl+Ctrl+A\"}","duplicate modifiers must not hide a different input operation");rejects("{\"action\":\"tabs\",\"tab\":\"other\"}","thread-wide tab enumeration must not take an alternate owner scope");
        browser_tool::PrivateText private_text;private_text.add("owned-secret-你好");private_text.add("123456");check(private_text.text("prefix owned-secret-你好 suffix 123456")=="prefix [redacted] suffix [redacted]","known private credential echoes must be redacted without retaining plaintext");check(private_text.text("safe public text")=="safe public text","credential echo redaction must retain unrelated page text");browser_tool::Object private_output;private_output.SetNamedValue(L"title",browser_tool::Value::CreateStringValue(L"owned-secret-你好"));browser_tool::Array nested;browser_tool::Object item;item.SetNamedValue(L"message",browser_tool::Value::CreateStringValue(L"OTP 123456"));nested.Append(item);private_output.SetNamedValue(L"nested",nested);private_text.redact(private_output);check(private_output.GetNamedString(L"title")==L"[redacted]"&&private_output.GetNamedArray(L"nested").GetAt(0).GetObject().GetNamedString(L"message")==L"OTP [redacted]","all public browser JSON string channels must redact known private echoes");
        const auto schema=browser_tool::Object::Parse(winrt::to_hstring(Request::schema()));check(schema.GetNamedArray(L"oneOf").Size()==Request::actions().size()&&!Request::actions().contains("fill-login")&&!Request::actions().contains("ask-user"),"advertised browser schema must match implemented action shapes and omit unavailable credential/handoff brokers");
        std::ofstream output(report);output<<"PASS: "<<checks<<" Windows browser agent policy checks; no browser or network created\n";return output?0:2;
    }catch(const std::exception& error){std::ofstream(report)<<"FAIL: "<<error.what()<<'\n';return 1;}catch(const winrt::hresult_error& error){std::ofstream(report)<<"FAIL: Windows browser policy API error "<<static_cast<unsigned>(error.code())<<'\n';return 1;}
}
} // namespace coincide
